:root{font-family:Arial,Helvetica,sans-serif;color:#26302c;background:#f6f5ef;--ink:#26302c;--muted:#67736b;--line:#d9ddd3;--green:#365541}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font:15px/1.55 Arial,Helvetica,sans-serif;background:#f6f5ef;color:#26302c}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button,a,input,select,textarea{outline-offset:5px}button,a{touch-action:manipulation}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid #506e43}a:hover{text-decoration:underline}.samplebar{padding:8px 5%;background:#e6eade;color:#475b46;display:flex;justify-content:space-between;gap:15px;font-size:11px}.samplebar a{font-weight:bold;text-decoration:underline}.shell{max-width:1280px;margin:auto;padding:0 5%}header{display:flex;justify-content:space-between;align-items:center;gap:22px;padding:24px 0;border-bottom:1px solid var(--line)}.logo{display:flex;align-items:center;gap:10px;font-size:14px;line-height:1.13;font-weight:800;letter-spacing:-.2px}.logo-mark{width:38px;height:38px;border:1.5px solid var(--green);display:grid;place-items:center;font-size:16px;border-radius:9px}.logo span small{font-size:8px;letter-spacing:2px;display:block;margin-top:4px;font-weight:500}nav{display:flex;align-items:center;gap:25px;font-size:12px}.pill{border:1px solid var(--ink);padding:11px 17px;border-radius:5px;display:inline-flex;align-items:center;gap:25px}.hero{display:grid;grid-template-columns:1fr 1fr;gap:55px;padding:68px 0 58px;align-items:center}.eyebrow{font-size:10px;letter-spacing:2px;font-weight:700;text-transform:uppercase;color:var(--green);display:flex;align-items:center;gap:9px;margin-bottom:21px}.eyebrow:before{content:'';width:6px;height:6px;background:#799157;border-radius:50%}h1{font-size:clamp(42px,4.8vw,68px);line-height:1.01;letter-spacing:-3.3px;font-weight:500;margin:0 0 24px}h1 em{font-family:Georgia,serif;font-weight:400;color:var(--green)}.intro{font-size:14px;line-height:1.8;color:var(--muted);max-width:370px}.ctas{display:flex;align-items:center;gap:25px;margin-top:30px;font-size:12px}.primary{display:inline-flex;justify-content:space-between;align-items:center;gap:35px;background:var(--green);color:white;padding:15px 20px;border:0;border-radius:5px}.smallnote{margin-top:20px;font-size:10px;color:var(--muted)}.viewer{background:#e9eade;border:1px solid #d6dacd;border-radius:10px;overflow:hidden;min-width:0}.viewer-top,.viewer-bottom{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;gap:10px;font-size:10px;color:#626e60}.viewer-top{border-bottom:1px solid #d2d7c9}.viewer-top b{color:#344732;font-size:11px}.viewer-bottom{background:#eef0e7}.artboard{height:307px;position:relative;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#f1f1e9,#e2e5d6)}.artboard svg{width:100%;height:100%;filter:drop-shadow(0 19px 12px #52624116)}.artboard.wire .solid{fill:transparent!important;stroke:#415c40;stroke-width:1.4}.artboard.wire .shade{opacity:.15}.segments{display:flex;gap:3px;background:#e0e4d8;padding:3px;border-radius:4px}.segments button{border:0;background:transparent;color:#62745b;font-size:10px;padding:5px 11px;border-radius:3px}.segments button.active{background:white;color:#2f4930;box-shadow:0 1px 2px #24372011}.service-strip{display:grid;grid-template-columns:repeat(3,1fr);padding:22px 0 26px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);gap:25px}.service-strip div{font-size:11px;color:var(--muted)}.service-strip b{display:block;font-size:13px;color:var(--ink);margin-bottom:5px}.number{color:#7d8f6f;margin-right:13px;font-family:Georgia,serif;font-style:italic}.section{padding:58px 0}.section-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;margin-bottom:25px}.section-heading h2{font-size:32px;letter-spacing:-1.3px;line-height:1.12;font-weight:500;margin:0}.section-heading p{font-size:12px;color:var(--muted);max-width:340px;margin:0}.filters{display:flex;gap:8px;margin:25px 0 20px;flex-wrap:wrap}.filters button{border:1px solid #d4d9cd;background:none;color:#576752;padding:8px 15px;border-radius:4px;font-size:11px}.filters button.active{color:white;background:var(--green);border-color:var(--green)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:19px}.work-card{min-width:0}.work-art{height:184px;border-radius:7px;background:#e9eadd;overflow:hidden;display:grid;place-items:center}.work-art svg{width:100%;height:100%;transition:transform .4s}.work-card:hover svg{transform:scale(1.04)}.work-card h3{font-size:13px;font-weight:600;margin:13px 0 3px}.work-card p{font-size:10px;color:var(--muted);margin:0}.tag{font-size:8px;letter-spacing:1px;color:#637957;text-transform:uppercase;margin-top:10px}.brief{display:grid;grid-template-columns:.85fr 1.15fr;gap:75px;background:#e9eddf;border-radius:9px;padding:40px;margin-bottom:30px}.brief h2{font-size:35px;line-height:1.1;font-weight:500;letter-spacing:-1.4px;margin:0 0 15px}.brief p{font-size:12px;color:#65745f;max-width:275px}.brief ol{padding-left:17px;font-size:11px;color:#52634c;line-height:2.2;margin-top:25px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.formgrid label{display:block;font-size:10px;color:#4b5b45;margin-bottom:6px;font-weight:bold}select,input,textarea{background:#f9faf5;border:1px solid #cdd5c4;border-radius:4px;width:100%;padding:10px;color:#3f5039;font-size:12px;min-width:0}textarea{resize:vertical;min-height:80px}.wide{grid-column:1/-1}.brief .primary{font-size:12px;margin-top:17px;width:100%}.result{background:#f6f8ef;border:1px solid #c6d2b5;padding:13px;border-radius:5px;margin-top:13px;font-size:11px;white-space:pre-line}.result[hidden]{display:none}.faq{margin:35px 0 45px}.faq details{border-bottom:1px solid var(--line);padding:16px 0;font-size:12px}.faq summary{cursor:pointer;font-weight:600}.faq p{color:var(--muted);max-width:760px}.foot{display:flex;justify-content:space-between;align-items:center;gap:25px;border-top:1px solid var(--line);padding:22px 0 30px;font-size:10px;color:var(--muted)}.foot a{text-decoration:underline}.wp-site-blocks{padding:0!important}.wp-block-post-content{margin:0!important}.skip-link{position:absolute;left:10px;top:-100px;background:white;z-index:100}.skip-link:focus{top:10px}@media(max-width:750px){header{padding:19px 0}nav a:not(.pill){display:none}nav{gap:0}.hero{grid-template-columns:1fr;gap:30px;padding:37px 0 32px}h1{font-size:51px;letter-spacing:-2.5px}.intro{max-width:100%}.artboard{height:260px}.service-strip{gap:13px}.service-strip b{font-size:11px}.service-strip div{font-size:10px}.number{display:block}.section{padding:37px 0}.section-heading{display:block}.section-heading p{margin-top:14px}.cards{grid-template-columns:1fr}.work-art{height:225px}.work-card{margin-bottom:10px}.brief{grid-template-columns:1fr;gap:24px;padding:26px 20px}.brief ol{display:none}.brief h2{font-size:31px}.brief p{max-width:100%}.samplebar{font-size:9px}.foot{align-items:flex-start;flex-direction:column;gap:10px}.formgrid{gap:13px}.ctas{gap:18px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.work-art svg{transition:none}}@media print{.samplebar,.filters,.brief,.faq,.foot,.service-strip,nav{display:none}.shell{padding:0 35px}.hero{padding:25px 0;gap:35px}.section{padding:20px 0}.cards{grid-template-columns:repeat(3,1fr)}.work-art{height:140px}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}h1{font-size:48px}.artboard{height:250px}@page{size:A4 landscape;margin:8mm}}

.wp-site-blocks{padding:0!important}.wp-block-post-content{margin:0!important}

const art=document.querySelector('#main-art');
document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{
 document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});
 art.classList.toggle('wire',button.dataset.mode==='wire');
}));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{
 document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});
 document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter});
 document.querySelector('#portfolio-count').textContent=button.dataset.filter==='all'?'3 sample studies':'1 sample study';
}));
document.querySelector('#project-brief').addEventListener('submit',event=>{
 event.preventDefault();
 const data=new FormData(event.currentTarget);
 const result=document.querySelector('#brief-result');
 result.hidden=false;
 result.textContent='Project brief ready\n\nService: '+data.get('service')+'\nUse: '+data.get('use')+'\nTiming: '+data.get('timing')+'\nReferences: '+data.get('reference')+'\nDetails: '+data.get('details')+'\n\nDemo preview · this brief stays in your browser.';
 result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});
});
